#include "rf_gate_model.h"

#include <stddef.h>

typedef struct {
    int16_t feature;
    int32_t left;
    int32_t right;
    double threshold;
    double probability;
} RfGateNode;

/* Feature order:
 * 00: v0
 * 01: v1
 * 02: v2
 * 03: v3
 * 04: v4
 * 05: v5
 * 06: v6
 * 07: v7
 * 08: v8
 * 09: v9
 * 10: v10
 * 11: v11
 * 12: v12
 * 13: v13
 * 14: abs_v0
 * 15: abs_v1
 * 16: abs_v2
 * 17: abs_v3
 * 18: abs_v4
 * 19: abs_v5
 * 20: abs_v6
 * 21: abs_v7
 * 22: abs_v8
 * 23: abs_v9
 * 24: abs_v10
 * 25: abs_v11
 * 26: abs_v12
 * 27: abs_v13
 * 28: sq_v0
 * 29: sq_v1
 * 30: sq_v2
 * 31: sq_v3
 * 32: sq_v4
 * 33: sq_v5
 * 34: sq_v6
 * 35: sq_v7
 * 36: sq_v8
 * 37: sq_v9
 * 38: sq_v10
 * 39: sq_v11
 * 40: sq_v12
 * 41: sq_v13
 * 42: amount_mcc
 * 43: amount_online
 * 44: amount_card_present
 * 45: amount_unknown_merchant
 * 46: amount_vs_avg_amount
 * 47: avg_ratio_merchant_avg
 * 48: hour_mcc
 * 49: last_tx_count
 * 50: last_home_distance
 * 51: home_mcc
 * 52: tx_count_mcc
 * 53: online_mcc
 * 54: card_mcc
 * 55: unknown_mcc
 */
void rf_gate_vector_poly_features(const int16_t query[FASTVECTOR_DIMENSIONS],
                                  float features[RF_GATE_FEATURE_COUNT]) {
    for (uint32_t i = 0; i < FASTVECTOR_DIMENSIONS; i++) {
        features[i] = (float)query[i];
    }
    for (uint32_t i = 0; i < FASTVECTOR_DIMENSIONS; i++) {
        float value = features[i];
        features[14u + i] = value < 0.0f ? -value : value;
    }
    for (uint32_t i = 0; i < FASTVECTOR_DIMENSIONS; i++) {
        float value = features[i];
        features[28u + i] = (value * value) / 10000.0f;
    }
    features[42u] = (features[0u] * features[12u]) / 10000.0f;
    features[43u] = (features[0u] * features[9u]) / 10000.0f;
    features[44u] = (features[0u] * features[10u]) / 10000.0f;
    features[45u] = (features[0u] * features[11u]) / 10000.0f;
    features[46u] = (features[2u] * features[0u]) / 10000.0f;
    features[47u] = (features[2u] * features[13u]) / 10000.0f;
    features[48u] = (features[3u] * features[12u]) / 10000.0f;
    features[49u] = (features[5u] * features[8u]) / 10000.0f;
    features[50u] = (features[6u] * features[7u]) / 10000.0f;
    features[51u] = (features[7u] * features[12u]) / 10000.0f;
    features[52u] = (features[8u] * features[12u]) / 10000.0f;
    features[53u] = (features[9u] * features[12u]) / 10000.0f;
    features[54u] = (features[10u] * features[12u]) / 10000.0f;
    features[55u] = (features[11u] * features[12u]) / 10000.0f;
}

