static double predict_tree(uint32_t root, const float features[RF_GATE_FEATURE_COUNT]) {
    uint32_t node_id = root;
    for (;;) {
        const RfGateNode *node = &RF_GATE_NODES[node_id];
        if (node->feature < 0) {
            return node->probability;
        }
        node_id = ((double)features[node->feature] <= node->threshold) ?
            (uint32_t)node->left : (uint32_t)node->right;
    }
}

double rf_gate_predict_fraud_probability_from_features(const float features[RF_GATE_FEATURE_COUNT]) {
    double sum = 0.0;
    for (uint32_t tree = 0; tree < RF_GATE_TREE_COUNT; tree++) {
        sum += predict_tree(RF_GATE_ROOTS[tree], features);
    }
    return sum / (double)RF_GATE_TREE_COUNT;
}

double rf_gate_predict_fraud_probability(const int16_t query[FASTVECTOR_DIMENSIONS]) {
    float features[RF_GATE_FEATURE_COUNT];
    rf_gate_vector_poly_features(query, features);
    return rf_gate_predict_fraud_probability_from_features(features);
}

RfGateDecision rf_gate_decide_probability(double probability) {
    if (probability <= RF_GATE_LOW_THRESHOLD) {
        return RF_GATE_DECISION_LEGIT;
    }
    if (probability >= RF_GATE_HIGH_THRESHOLD) {
        return RF_GATE_DECISION_FRAUD;
    }
    return RF_GATE_DECISION_FALLBACK;
}

RfGateDecision rf_gate_decide(const int16_t query[FASTVECTOR_DIMENSIONS],
                              double *out_probability) {
    double probability = rf_gate_predict_fraud_probability(query);
    if (out_probability != NULL) {
        *out_probability = probability;
    }
    return rf_gate_decide_probability(probability);
}
